<script setup lang="ts">
import {ElButton, ElDialog, ElSelect, ElOption, ElInput, ElTable, ElTableColumn, ElPagination, ElCheckbox, ElCheckboxGroup} from 'element-plus'
import {computed,ref,watch} from 'vue'
import AdminSelectedRowsDialog from '../../shared/list/AdminSelectedRowsDialog.vue'
import AdminListPager from '../../shared/list/AdminListPager.vue'
import AdminStatusBadge from '../../shared/list/AdminStatusBadge.vue'
import AdminSelectionBar from '../../shared/list/AdminSelectionBar.vue'
import {confirmAction} from '../../shared/confirm'
import {api,ApiError} from '../../api'
import {base,reasonText,type DiningStaff,type MemberChoice} from './types'
const listSearch=ref(''),listEnabled=ref(''),listLoading=ref(false)
let listGeneration=0
const checked=ref<DiningStaff[]>([]),selectionVersion=ref(0),comparison=ref(false)
const comparisonRows=computed(()=>checked.value.map(r=>({name:r.name,memberNo:r.memberNo,permissions:r.permissions.join('、'),status:r.enabled?'已授权':'已停用'})))
const pageSize=ref(20)
const editOpen=ref(false)
const props=defineProps<{restaurantId:string;canManage:boolean}>()
const items=ref<DiningStaff[]>([]),query=ref(''),choices=ref<MemberChoice[]>([]),selected=ref<MemberChoice|null>(null),permissions=ref<string[]>(['products','orders']),enabled=ref(true),busy=ref(false),error=ref(''),notice=ref(''),page=ref(1),total=ref(0),revision=ref(0)
let generation=0
watch(query,()=>{choices.value=[];selected.value=null;revision.value=0;generation++},{flush:'sync'})
async function load(){const current=++listGeneration,target=props.restaurantId;listLoading.value=true;checked.value=[];items.value=[];comparison.value=false;error.value='';try{const result=await api<{items:DiningStaff[];total:number}>(`${base}/restaurants/${target}/staff?page=${page.value}&pageSize=${pageSize.value}&search=${encodeURIComponent(listSearch.value.trim())}&enabled=${listEnabled.value}`);if(current===listGeneration&&target===props.restaurantId){items.value=result.items;total.value=result.total}}catch(e){if(current===listGeneration&&target===props.restaurantId)error.value=reasonText(e)}finally{if(current===listGeneration)listLoading.value=false}}
async function search(){if(busy.value)return;const current=++generation;busy.value=true;error.value='';try{const result=await api<{members:MemberChoice[]}>(`${base}/restaurants/${props.restaurantId}/staff?${new URLSearchParams({memberSearch:query.value.trim()})}`);if(current===generation){choices.value=result.members;if(!choices.value.length)error.value='未找到已启用会员，请核对编号或昵称。'}}catch(e){if(current===generation)error.value=reasonText(e)}finally{busy.value=false}}
async function save(){if(!props.canManage||!selected.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{await api(`${base}/restaurants/${props.restaurantId}/staff`,{method:'POST',body:JSON.stringify({memberId:selected.value.id,permissions:[...permissions.value],enabled:enabled.value,revision:revision.value})});query.value='';selected.value=null;editOpen.value=false;await load();notice.value='人员授权已保存。'}catch(e){error.value=reasonText(e)+(e instanceof ApiError&&e.status===409?'；当前授权草稿已保留，请重新读取核对最新授权。':'')}finally{busy.value=false}}
let editBaseline=''
const editSignature=()=>JSON.stringify([selected.value,permissions.value,enabled.value])
function openNew(){editOpen.value=true;query.value='';selected.value=null;revision.value=0;permissions.value=['products','orders'];enabled.value=true;editBaseline=editSignature()}
async function canClose(){return !busy.value&&(!editOpen.value||editSignature()===editBaseline||await confirmAction('人员授权尚未保存，确定关闭吗？'))}
async function closeStaff(done?:()=>void){if(!await canClose())return;editOpen.value=false;done?.()}
defineExpose({canClose})
function edit(item:DiningStaff){editOpen.value=true;query.value=item.memberNo;selected.value={id:item.memberId,name:item.name,memberNo:item.memberNo};permissions.value=[...item.permissions];enabled.value=item.enabled;revision.value=item.revision;editBaseline=editSignature()}
watch(()=>props.restaurantId,()=>{generation++;page.value=1;listSearch.value='';listEnabled.value='';editOpen.value=false;items.value=[];query.value='';error.value='';load()},{immediate:true})
</script>
<template><section class="panel admin-list-page"><h2>餐饮店管理人员</h2><form class="toolbar" @submit.prevent="page=1;load()"><label>关键词<el-input v-model="listSearch" aria-label="列表关键词" maxlength="100" :disabled="busy"/></label><label>状态<select v-model="listEnabled" :disabled="busy"><option value="">全部状态</option><option value="true">启用</option><option value="false">停用</option></select></label><el-button native-type="submit" type="primary" :disabled="busy">查询</el-button><el-button :disabled="busy" @click="listSearch='';listEnabled='';page=1;load()">重置</el-button></form><p>选择已注册会员，授权后可在小程序个人中心进入联盟中心。</p><p v-if="error" role="alert" class="error">{{error}} <el-button @click="load">重新读取</el-button></p><p v-if="notice" role="status">{{notice}}</p><el-button v-if="canManage" type="primary" :disabled="busy" @click="openNew()">新增人员授权</el-button><AdminSelectionBar :count="checked.length" :loading="busy||listLoading" @clear="checked=[];selectionVersion++"><el-button :disabled="!checked.length" @click="comparison=true">对比所选授权</el-button></AdminSelectionBar><el-table :key="selectionVersion" class="admin-list-table" :data="items" :empty-text="listLoading?'正在读取人员授权…':error?'读取失败，请重试。':'尚未授权管理人员'" @selection-change="checked=$event"><el-table-column type="selection" width="50"/><el-table-column prop="name" label="会员"/><el-table-column prop="memberNo" label="会员编号"/><el-table-column label="权限"><template #default="{row}">{{row.permissions.map((p:string)=>({products:'商品',orders:'订单',finance:'佣金'}[p as 'products']||p)).join('、')}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><AdminStatusBadge :status="row.enabled?'ENABLED':'DISABLED'" :label="row.enabled?'已授权':'已停用'" :tone="row.enabled?'success':'neutral'"/></template></el-table-column><el-table-column v-if="canManage" label="操作"><template #default="{row}"><el-button link @click="edit(row as DiningStaff)">编辑授权</el-button></template></el-table-column></el-table><AdminListPager v-if="!error" :page="page" :page-size="pageSize" :total="total" :loading="busy||listLoading" @change="(p,s)=>{page=p;pageSize=s;load()}"/><el-dialog v-model="editOpen" :before-close="closeStaff" title="人员授权" width="min(700px,94vw)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><form v-if="canManage" aria-label="人员授权" @submit.prevent="save"><p v-if="error" class="error" role="alert">{{error}}</p><div class="toolbar"><el-input v-model="query" :disabled="busy" aria-label="查找会员" placeholder="输入会员编号或昵称" style="width:280px" @keydown.enter.prevent="search"/><el-button :disabled="busy||query.trim().length<2" @click="search">查找会员</el-button></div><ul v-if="choices.length"><li v-for="member in choices" :key="member.id">{{member.name}} · {{member.memberNo}} <el-button link @click="selected={...member};choices=[]">选择</el-button></li></ul><p v-if="selected" role="status">已选择：{{selected.name}} · {{selected.memberNo}}</p><div class="toolbar"><el-checkbox-group v-model="permissions" :disabled="busy"><el-checkbox value="products">商品上下架</el-checkbox><el-checkbox value="orders">订单</el-checkbox><el-checkbox value="finance">佣金</el-checkbox></el-checkbox-group><el-checkbox v-model="enabled" :disabled="busy">启用授权</el-checkbox><el-button native-type="submit" type="primary" :loading="busy" :disabled="!selected||!permissions.length">保存授权</el-button></div></form><template #footer><el-button :disabled="busy" @click="closeStaff()">取消</el-button></template></el-dialog><AdminSelectedRowsDialog v-model="comparison" title="人员授权对比" :rows="comparisonRows" :columns="[{key:'name',label:'人员'},{key:'memberNo',label:'会员编号'},{key:'permissions',label:'权限'},{key:'status',label:'状态'}]"/></section></template>
